    "راجع البيانات قبل الحفظ؛ لا تتوفر عملية تعديل للدواء ضمن العقد الحالي.":
      "Kaydetmeden önce verileri inceleyin; Mevcut sözleşmede herhangi bir ilaç değişikliği süreci bulunmamaktadır.",
    "راجع الدواء والكمية ووقت الاحتياج، ثم حدّث حالة الطلب وأرسل ردًا واضحًا لصاحبه.":
      "İlacı, miktarı ve ihtiyaç zamanını gözden geçirin, ardından sipariş durumunu güncelleyin ve sahibine net bir yanıt gönderin.",
    "راجع الطلبات الواردة، تحقق من المخزون، ثم أرسل للمريض إجابة دقيقة أو اقترح بديلاً متاحًا.":
      "Gelen siparişleri gözden geçirin, envanteri kontrol edin ve ardından hastaya doğru bir yanıt gönderin veya mevcut bir alternatif önerin.",
    "راجع بيانات الدواء وحالة العبوات، ثم وافق على العرض أو ارفضه أو أكد استلامه مع إرسال رد واضح للمتبرع.":
      "İlaç bilgilerini ve paketin durumunu inceleyin, ardından donöre net bir yanıt vererek teklifi kabul edin, reddedin veya onaylayın.",
    "راجع ساعات الفتح والإغلاق وتأكد من عدم تداخلها.":
      "Açılış ve kapanış saatlerini gözden geçirin ve çakışmadıklarından emin olun.",
    "راجع عمليات البحث السابقة وعد إلى البحث عن الدواء بسرعة.":
      "Önceki aramalarınızı gözden geçirin ve ilacınızı aramaya hızla geri dönün.",
